components.css:
.ds-download{font-family:var(--sans);color:var(--blue);text-underline-offset:.22em}.ds-download:hover{color:var(--fg)}.ds-download{display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 44px;
  font-size: 0.95rem;
  font-weight: 600;}
.ds-download small{font-size: 0.8rem;
  font-weight: 400;
  margin-left: 0.15rem;}
.ds-download.ds-primary{padding: 0.5rem 0.95rem;
  color: var(--bg);
  background: var(--fg);
  text-decoration: none;
  transition: background 0.3s;}
.ds-download.ds-primary:hover{color: var(--bg);
  background: #fff;}
.ds-download[aria-disabled="true"],
.ds-requirements a[aria-disabled="true"]{color: var(--mute);
  cursor: default;
  text-decoration: none;
  background: none;
  padding: 0;}.ds-control:focus-visible{outline:2px solid var(--fg);outline-offset:4px}

