.ds-rail{display:flex}.ds-tab{font-family:var(--sans)}.ds-tab{position: relative;
  flex: 1;
  min-width: max-content;
  border: 0;
  padding: 15px 10px 6px 0;
  min-height: 48px;
  background: none;
  color: var(--mute);
  text-align: left;
  font-size: 0.86rem;
  white-space: nowrap;}
.ds-tab::before,
.ds-tab::after{content: "";
  position: absolute;
  top: 3px;
  left: 0;
  right: 7px;
  height: 2px;
  background: var(--line);}
.ds-tab::after{background: var(--fg);
  transform: scaleX(var(--p, 0));
  transform-origin: left center;}
.ds-tab[aria-selected="true"]{color: var(--fg);}
.ds-tab[aria-selected="true"]::before{background: var(--blue);}
.ds-tab:hover{color: var(--fg);}.ds-control:focus-visible{outline:2px solid var(--fg);outline-offset:4px}

.ds-os{font-family:var(--sans)}.ds-os{min-height: 44px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: none;
  padding: 0.3rem 0;
  font-size: 0.8rem;
  color: var(--mute);}
.ds-os[aria-checked="true"]{color: var(--fg);
  border-bottom-color: var(--blue);}
.ds-os:hover{color: var(--fg);}.ds-control:focus-visible{outline:2px solid var(--fg);outline-offset:4px}

.ds-copy{font-family:var(--sans)}.ds-command code{font:400 .75rem/1.7 var(--mono)}.ds-command{display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 1px solid var(--line);
  padding: 0.25rem 0 0.5rem;
  min-width: 0;}
.ds-command code{min-width: 0;
  overflow-wrap: anywhere;
  color: var(--fg);}
.ds-copy{min-height: 44px;
  flex-shrink: 0;
  padding: 0.3rem 0 0.3rem 0.6rem;
  border: 0;
  background: none;
  color: var(--blue);
  font-size: 0.82rem;
  text-decoration: underline;
  text-underline-offset: 0.22em;}
.ds-copy:hover{color: var(--fg);}.ds-control:focus-visible{outline:2px solid var(--fg);outline-offset:4px}

.ds-links{font-family:var(--sans)}.ds-links{display: flex;
  gap: 1.5rem;
  margin-left: auto;}
.ds-links a{display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 0.88rem;
  color: var(--fg);
  text-decoration: none;}
.ds-links a:hover{text-decoration: underline;}.ds-control:focus-visible{outline:2px solid var(--fg);outline-offset:4px}
